// Main Page Component
const AdminKeuanganPage: React.FC = () => {
    const [pengeluaranList, setPengeluaranList] = useState<Pengeluaran[]>([]);
    const [loading, setLoading] = useState(true);
    const [isFormModalOpen, setIsFormModalOpen] = useState(false);
    const [pengeluaranToEdit, setPengeluaranToEdit] = useState<Pengeluaran | null>(null);
    const [pengeluaranToDelete, setPengeluaranToDelete] = useState<Pengeluaran | null>(null);

    // Pagination
    const [currentPage, setCurrentPage] = useState(1);
    const [itemsPerPage, setItemsPerPage] = useState<number | 'all'>(10);

    const fetchData = useCallback(async () => {
        try {
            setLoading(true);
            const data = await getAllPengeluaran();
            setPengeluaranList(data);
        } catch (error) {
            console.error("Failed to fetch data", error);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    const paginatedPengeluaran = useMemo(() => {
        if (itemsPerPage === 'all') return pengeluaranList;
        const startIndex = (currentPage - 1) * itemsPerPage;
        return pengeluaranList.slice(startIndex, startIndex + itemsPerPage);
    }, [pengeluaranList, currentPage, itemsPerPage]);

    const totalPages = itemsPerPage === 'all' ? 1 : Math.ceil(pengeluaranList.length / itemsPerPage);

    const handleSave = async (pengeluaran: Omit<Pengeluaran, 'id'> | Pengeluaran) => {
        if ('id' in pengeluaran) {
            await updatePengeluaran(pengeluaran.id, pengeluaran);
        } else {
            await createPengeluaran(pengeluaran as Omit<Pengeluaran, 'id'>);
        }
        fetchData();
        setIsFormModalOpen(false);
        setPengeluaranToEdit(null);
    };

    const handleDeleteConfirm = async (id: string) => {
        await deletePengeluaran(id);
        fetchData();
        setPengeluaranToDelete(null);
    };

    const openFormModal = (pengeluaran: Pengeluaran | null = null) => {
        setPengeluaranToEdit(pengeluaran);
        setIsFormModalOpen(true);
    };

    const totalPengeluaranBulanIni = useMemo(() => {
        const today = new Date();
        const currentMonth = today.getMonth();
        const currentYear = today.getFullYear();

        return pengeluaranList
            .filter(p => {
                const pDate = new Date(p.date);
                return pDate.getMonth() === currentMonth && pDate.getFullYear() === currentYear;
            })
            .reduce((sum, p) => sum + p.amount, 0);
    }, [pengeluaranList]);

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('id-ID', { 
            style: 'currency', 
            currency: 'IDR', 
            minimumFractionDigits: 2,
            maximumFractionDigits: 2 
        }).format(amount).replace(/\s/g, ' ');
    };

    return (
        <div className="space-y-6 max-w-7xl mx-auto">
            {/* Header Section */}
            <div className="bg-white p-6 rounded-2xl border border-slate-200/60 shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h1 className="text-2xl font-extrabold text-slate-800 tracking-tight">Manajemen Keuangan</h1>
                    <p className="text-slate-500 text-sm mt-0.5 font-medium">Kelola catatan pengeluaran operasional.</p>
                </div>
                <button 
                    onClick={() => openFormModal()} 
                    className="bg-emerald-500 hover:bg-emerald-600 text-white font-bold py-2.5 px-5 rounded-xl shadow-lg shadow-emerald-500/20 transition-all flex items-center gap-2"
                >
                    <i className="fa-solid fa-plus text-sm"></i>
                    Tambah Pengeluaran
                </button>
            </div>

            {/* Summary Banner */}
            <div className="bg-white p-6 rounded-2xl border border-slate-200/60 shadow-sm flex items-center gap-6 animate-fade-in">
                <div className="flex-shrink-0 w-16 h-16 flex items-center justify-center rounded-2xl bg-rose-50 border border-rose-100 shadow-inner">
                  <i className="fa-solid fa-money-bill-transfer text-3xl text-rose-500"></i>
                </div>
                <div>
                    <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Total Pengeluaran Bulan Ini</p>
                    {loading ? 
                        <div className="h-10 w-48 bg-slate-100 rounded-lg animate-pulse"></div> :
                        <h2 className="text-3xl font-black text-slate-800 tracking-tight">
                            {formatCurrency(totalPengeluaranBulanIni).split(',')[0]}
                        </h2>
                    }
                </div>
            </div>

            {/* Content Table */}
            <div className="bg-white rounded-2xl border border-slate-200/60 shadow-sm overflow-hidden animate-fade-in">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left border-collapse">
                        <thead>
                            <tr className="bg-slate-50/50 border-b border-slate-100">
                                <th className="p-5 uppercase text-[11px] font-black text-slate-400 tracking-widest">Tanggal</th>
                                <th className="p-5 uppercase text-[11px] font-black text-slate-400 tracking-widest">Keterangan</th>
                                <th className="p-5 uppercase text-[11px] font-black text-slate-400 tracking-widest">Jumlah</th>
                                <th className="p-5 uppercase text-[11px] font-black text-slate-400 tracking-widest text-center">Aksi</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {loading ? (
                                Array.from({ length: 5 }).map((_, i) => (
                                    <tr key={i}>
                                        <td className="p-5" colSpan={4}><div className="h-6 bg-slate-50 rounded animate-pulse w-full"></div></td>
                                    </tr>
                                ))
                            ) : paginatedPengeluaran.map((pengeluaran) => (
                                <tr key={pengeluaran.id} className="hover:bg-slate-50/80 transition-colors group">
                                    <td className="p-5 text-slate-500 font-medium">
                                        {new Date(pengeluaran.date).toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' })}
                                    </td>
                                    <td className="p-5">
                                        <p className="font-bold text-slate-700 group-hover:text-slate-900 transition-colors">{pengeluaran.description}</p>
                                    </td>
                                    <td className="p-5 font-mono text-slate-600 font-medium">
                                        {formatCurrency(pengeluaran.amount)}
                                    </td>
                                    <td className="p-5">
                                        <div className="flex justify-center items-center gap-4">
                                            <button 
                                                onClick={() => openFormModal(pengeluaran)} 
                                                className="text-slate-400 hover:text-indigo-600 transition-colors" 
                                                title="Edit Data"
                                            >
                                                <PencilIcon className="text-xl" />
                                            </button>
                                            <button 
                                                onClick={() => setPengeluaranToDelete(pengeluaran)} 
                                                className="text-slate-400 hover:text-rose-600 transition-colors" 
                                                title="Hapus Data"
                                            >
                                                <TrashIcon className="text-xl" />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                     {!loading && pengeluaranList.length === 0 && (
                        <div className="text-center py-20 px-6">
                            <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-slate-100 shadow-inner">
                                <BanknotesIcon className="text-4xl text-slate-300"/>
                            </div>
                            <h3 className="font-bold text-slate-800 text-lg">Belum Ada Pengeluaran</h3>
                            <p className="text-slate-500 max-w-xs mx-auto mt-2">Catatan pengeluaran operasional Anda akan muncul di sini setelah Anda menambahkannya.</p>
                        </div>
                    )}
                </div>

                {/* Pagination Controls */}
                {!loading && pengeluaranList.length > 0 && (
                    <div className="p-5 border-t border-slate-100 bg-slate-50/30 flex flex-col md:flex-row justify-between items-center gap-4">
                        <div className="flex items-center text-xs font-bold text-slate-400 uppercase tracking-wider">
                            <span className="mr-3">Tampilkan</span>
                            <select
                                value={itemsPerPage}
                                onChange={(e) => setItemsPerPage(e.target.value === 'all' ? 'all' : Number(e.target.value))}
                                className="bg-white border border-slate-200 rounded-lg px-2 py-1 focus:outline-none focus:ring-1 focus:ring-primary text-slate-700"
                            >
                                <option value={10}>10</option>
                                <option value={25}>25</option>
                                <option value="all">Semua</option>
                            </select>
                            <span className="ml-3">Total: {pengeluaranList.length} Catatan</span>
                        </div>
                        {itemsPerPage !== 'all' && (
                            <div className="flex items-center gap-2">
                                <button
                                    onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                                    disabled={currentPage === 1}
                                    className="p-2 border border-slate-200 rounded-lg bg-white text-slate-400 hover:text-primary hover:border-primary disabled:opacity-30 disabled:hover:text-slate-400 disabled:hover:border-slate-200 transition-all"
                                >
                                    <i className="fa-solid fa-chevron-left"></i>
                                </button>
                                <div className="px-4 py-1.5 bg-white border border-slate-200 rounded-lg font-bold text-slate-700 text-xs">
                                    Halaman {currentPage} / {totalPages}
                                </div>
                                <button
                                    onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                                    disabled={currentPage === totalPages}
                                    className="p-2 border border-slate-200 rounded-lg bg-white text-slate-400 hover:text-primary hover:border-primary disabled:opacity-30 disabled:hover:text-slate-400 disabled:hover:border-slate-200 transition-all"
                                >
                                    <i className="fa-solid fa-chevron-right"></i>
                                </button>
                            </div>
                        )}
                    </div>
                )}
            </div>

            {/* Modals */}
            <Modal isOpen={isFormModalOpen} onClose={() => { setIsFormModalOpen(false); setPengeluaranToEdit(null); }} title={pengeluaranToEdit ? 'Edit Pengeluaran' : 'Tambah Pengeluaran Baru'} size="lg">
                <PengeluaranForm pengeluaran={pengeluaranToEdit} onSave={handleSave} onCancel={() => { setIsFormModalOpen(false); setPengeluaranToEdit(null); }} />
            </Modal>

            <Modal isOpen={!!pengeluaranToDelete} onClose={() => setPengeluaranToDelete(null)} title="Hapus Data Pengeluaran" size="md">
                {pengeluaranToDelete && (
                    <div className="text-center">
                        <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-rose-100">
                             <TrashIcon className="text-3xl text-rose-500"/>
                        </div>
                        <p className="text-slate-700 font-medium">
                            Hapus catatan pengeluaran <span className="font-bold">"{pengeluaranToDelete.description}"</span>?
                        </p>
                        <div className="mt-6 flex justify-center gap-3">
                            <button onClick={() => setPengeluaranToDelete(null)} className="px-6 py-2.5 rounded-xl text-slate-600 font-bold hover:bg-slate-100 transition-colors">Batal</button>
                            <button 
                                onClick={() => handleDeleteConfirm(pengeluaranToDelete.id)} 
                                className="px-6 py-2.5 rounded-xl bg-rose-500 text-white font-bold hover:bg-rose-600 shadow-lg shadow-rose-500/20 transition-all"
                            >
                                Ya, Hapus Permanen
                            </button>
                        </div>
                    </div>
                )}
            </Modal>
        </div>
    );
};

export default AdminKeuanganPage;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import type { Warga, Dukuh, RT } from '@/types';
import { getAllWarga, getAllDukuh, getAllRT, createWarga, updateWarga, deleteWarga } from '@/services/api';
import Modal from '@/components/Modal';
import { TrashIcon, PencilIcon, SearchIcon, UsersIcon } from '@/components/icons';

// Form Component for Add/Edit Warga
const WargaForm: React.FC<{
  warga?: Warga | null;
  dukuhList: Dukuh[];
  rtList: RT[];
  onSave: (warga: Omit<Warga, 'id' | 'totalDebt'> | Warga) => void;
  onCancel: () => void;
}> = ({ warga, dukuhList, rtList, onSave, onCancel }) => {
  const [formData, setFormData] = useState({
    name: warga?.name || '',
    dukuhId: warga?.dukuhId || (dukuhList[0]?.id || 0),
    rtId: warga?.rtId || (rtList[0]?.id || 0),
    dailyFee: warga?.dailyFee || 2000,
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(warga ? { ...warga, ...formData } : formData);
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <div>
        <label className="block text-sm font-bold text-slate-700 mb-1">Nama Lengkap Warga</label>
        <input 
          type="text" 
          value={formData.name} 
          onChange={e => setFormData({...formData, name: e.target.value})} 
          className="w-full p-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary outline-none" 
          placeholder="Masukkan nama lengkap"
          required 
        />
      </div>
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-bold text-slate-700 mb-1">Dukuh / Wilayah</label>
          <select 
            value={formData.dukuhId} 
            onChange={e => setFormData({...formData, dukuhId: Number(e.target.value)})}
            className="w-full p-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary outline-none"
          >
            {dukuhList.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-sm font-bold text-slate-700 mb-1">RT</label>
          <select 
            value={formData.rtId} 
            onChange={e => setFormData({...formData, rtId: Number(e.target.value)})}
            className="w-full p-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary outline-none"
          >
            {rtList.map(rt => <option key={rt.id} value={rt.id}>RT {rt.number}</option>)}
          </select>
        </div>
      </div>
      <div>
        <label className="block text-sm font-bold text-slate-700 mb-1">Tarif Iuran Harian (Rp)</label>
        <input 
          type="number" 
          value={formData.dailyFee} 
          onChange={e => setFormData({...formData, dailyFee: Number(e.target.value)})} 
          className="w-full p-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-primary outline-none font-mono font-bold" 
          required 
        />
      </div>
      <div className="flex justify-end gap-3 pt-4">
        <button type="button" onClick={onCancel} className="px-4 py-2 rounded-lg font-bold text-slate-500 hover:bg-slate-100 transition-colors">Batal</button>
        <button type="submit" className="px-6 py-2 rounded-lg font-bold bg-primary text-white hover:bg-primary-focus shadow-lg shadow-primary/20 transition-all">Simpan Data</button>
      </div>
    </form>
  );
};

const AdminWargaPage: React.FC = () => {
    const [wargaList, setWargaList] = useState<Warga[]>([]);
    const [dukuhList, setDukuhList] = useState<Dukuh[]>([]);
    const [rtList, setRtList] = useState<RT[]>([]);
    const [loading, setLoading] = useState(true);
    const [filters, setFilters] = useState({ search: '', dukuhId: 'all' });

    // Modals state
    const [isFormModalOpen, setIsFormModalOpen] = useState(false);
    const [selectedWarga, setSelectedWarga] = useState<Warga | null>(null);
    const [wargaToDelete, setWargaToDelete] = useState<Warga | null>(null);

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const [w, d, r] = await Promise.all([getAllWarga(), getAllDukuh(), getAllRT()]);
            setWargaList(w);
            setDukuhList(d);
            setRtList(r);
        } catch (error) {
            console.error("Failed to fetch warga data", error);
        } finally {
            setLoading(false);
        }
    }, []);

    useEffect(() => { fetchData(); }, [fetchData]);

    const filteredWarga = useMemo(() => {
        return wargaList.filter(w => {
            const matchSearch = w.name.toLowerCase().includes(filters.search.toLowerCase()) || w.id.includes(filters.search);
            const matchDukuh = filters.dukuhId === 'all' || w.dukuhId === Number(filters.dukuhId);
            return matchSearch && matchDukuh;
        });
    }, [wargaList, filters]);

    const getDukuhName = (id: number) => dukuhList.find(d => d.id === id)?.name || 'N/A';
    const getRTNumber = (id: number) => rtList.find(r => r.id === id)?.number || 'N/A';

    const handleSaveWarga = async (wargaData: Omit<Warga, 'id' | 'totalDebt'> | Warga) => {
        try {
            if ('id' in wargaData) {
                await updateWarga(wargaData.id, wargaData as Warga);
            } else {
                await createWarga(wargaData);
            }
            await fetchData();
            setIsFormModalOpen(false);
            setSelectedWarga(null);
        } catch (error) {
            alert("Gagal menyimpan data warga.");
        }
    };

    const handleDeleteConfirm = async (id: string) => {
        try {
            await deleteWarga(id);
            await fetchData();
            setWargaToDelete(null);
        } catch (error) {
            alert("Gagal menghapus data warga.");
        }
    };

    const openEditModal = (warga: Warga) => {
        setSelectedWarga(warga);
        setIsFormModalOpen(true);
    };

    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-2xl border border-slate-200/60 shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h1 className="text-2xl font-extrabold text-slate-800 tracking-tight">Data Warga</h1>
                    <p className="text-slate-500 text-sm mt-0.5 font-medium">Kelola daftar profil warga dan tarif iuran harian.</p>
                </div>
                <button 
                  onClick={() => { setSelectedWarga(null); setIsFormModalOpen(true); }}
                  className="bg-primary text-white px-5 py-2.5 rounded-xl font-bold hover:bg-primary-focus shadow-lg shadow-primary/20 transition-all flex items-center gap-2"
                >
                    <i className="fa-solid fa-plus text-sm"></i> Warga Baru
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-white p-4 rounded-2xl border border-slate-200/60 shadow-sm">
                <div className="relative">
                    <SearchIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                    <input 
                        type="text" 
                        placeholder="Cari nama atau ID..." 
                        className="w-full pl-10 pr-4 py-2.5 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all bg-slate-50/50"
                        onChange={(e) => setFilters({...filters, search: e.target.value})}
                    />
                </div>
                <select 
                    className="p-2.5 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary transition-all bg-slate-50/50 text-slate-600 font-medium"
                    onChange={(e) => setFilters({...filters, dukuhId: e.target.value})}
                    value={filters.dukuhId}
                >
                    <option value="all">Semua Dukuh</option>
                    {dukuhList.map(d => <option key={d.id} value={d.id}>{d.name}</option>)}
                </select>
            </div>

            <div className="bg-white rounded-2xl border border-slate-200/60 shadow-sm overflow-hidden animate-fade-in">
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-left border-collapse">
                        <thead>
                            <tr className="bg-slate-50/50 border-b border-slate-100">
                                <th className="p-5 uppercase text-[11px] font-black text-slate-400 tracking-widest">ID</th>
                                <th className="p-5 uppercase text-[11px] font-black text-slate-400 tracking-widest">Nama</th>
                                <th className="p-5 uppercase text-[11px] font-black text-slate-400 tracking-widest">Wilayah</th>
                                <th className="p-5 uppercase text-[11px] font-black text-slate-400 tracking-widest text-right">Tarif Harian</th>
                                <th className="p-5 uppercase text-[11px] font-black text-slate-400 tracking-widest text-center">Aksi</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {loading ? (
                                Array.from({ length: 5 }).map((_, i) => (
                                    <tr key={i}><td colSpan={5} className="p-5"><div className="h-6 bg-slate-50 rounded animate-pulse w-full"></div></td></tr>
                                ))
                            ) : filteredWarga.map(w => (
                                <tr key={w.id} className="hover:bg-slate-50 transition-colors group">
                                    <td className="p-5 font-mono text-slate-400 text-xs">{w.id}</td>
                                    <td className="p-5 font-bold text-slate-700 group-hover:text-slate-900 transition-colors">{w.name}</td>
                                    <td className="p-5 text-slate-500 font-medium">RT {getRTNumber(w.rtId)}, {getDukuhName(w.dukuhId)}</td>
                                    <td className="p-5 text-right font-mono font-bold text-slate-600">
                                        Rp{w.dailyFee.toLocaleString('id-ID')}
                                    </td>
                                    <td className="p-5">
                                        <div className="flex justify-center items-center gap-4">
                                            <button 
                                              onClick={() => openEditModal(w)}
                                              className="text-slate-400 hover:text-indigo-600 transition-colors"
                                              title="Edit Warga"
                                            >
                                                <PencilIcon className="text-xl" />
                                            </button>
                                            <button 
                                              onClick={() => setWargaToDelete(w)}
                                              className="text-slate-400 hover:text-rose-600 transition-colors"
                                              title="Hapus Warga"
                                            >
                                                <TrashIcon className="text-xl" />
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                            {!loading && filteredWarga.length === 0 && (
                                <tr>
                                    <td colSpan={5} className="p-12 text-center text-slate-400 italic">
                                        <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-slate-100">
                                            <UsersIcon className="text-3xl text-slate-200" />
                                        </div>
                                        Tidak ada data warga ditemukan.
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Modals */}
            <Modal 
              isOpen={isFormModalOpen} 
              onClose={() => { setIsFormModalOpen(false); setSelectedWarga(null); }} 
              title={selectedWarga ? 'Edit Data Warga' : 'Tambah Warga Baru'}
              size="lg"
            >
                <WargaForm 
                    warga={selectedWarga} 
                    dukuhList={dukuhList} 
                    rtList={rtList} 
                    onSave={handleSaveWarga} 
                    onCancel={() => { setIsFormModalOpen(false); setSelectedWarga(null); }} 
                />
            </Modal>

            <Modal isOpen={!!wargaToDelete} onClose={() => setWargaToDelete(null)} title="Hapus Data Warga" size="md">
                {wargaToDelete && (
                    <div className="text-center">
                        <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-4 border border-rose-100">
                             <TrashIcon className="text-3xl text-rose-500"/>
                        </div>
                        <p className="text-slate-700 font-medium">
                            Hapus data warga <span className="font-bold">"{wargaToDelete.name}"</span>?
                        </p>
