    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const [w, d, r] = await Promise.all([getAllWarga(), getAllDukuh(), getAllRT()]);
            setWargaList(w);
            setDukuhList(d);
            setRtList(r);
        } catch (error) {
            console.error("Failed to fetch warga data", error);
        } finally {
            setLoading(false);
