import React, { useState, useEffect, useMemo } from 'react';
import { getReports, getPengeluaran } from '@/services/api';
import type { Transaksi, Pengeluaran } from '@/types';
import { DownloadIcon } from '@/components/icons';

const DailyReport: React.FC = () => {
    const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
    const [reports, setReports] = useState<any[]>([]);
    const [expenses, setExpenses] = useState<Pengeluaran[]>([]);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        const fetch = async () => {
            setLoading(true);
            const d = new Date(date);
            const [r, e] = await Promise.all([getReports({ startDate: d, endDate: d }), getPengeluaran({ startDate: d, endDate: d })]);
            setReports(r);
            setExpenses(e);
            setLoading(false);
        };
        fetch();
    }, [date]);

    const handlePrint = () => {
        const printWindow = window.open('', '_blank');
        if (!printWindow) return;
        const rows = reports.map(r => `<tr><td>${new Date(r.timestamp).toLocaleTimeString('id-ID', {hour:'2-digit', minute:'2-digit'})}</td><td>${r.wargaName}</td><td>${r.rtNumber}/${r.dukuhName}</td><td style="text-align:right">Rp${r.amount.toLocaleString('id-ID')}</td></tr>`).join('');
        printWindow.document.write(`<html><head><style>body{font-family:sans-serif;padding:50px;color:#1e293b;} .kop{text-align:center;border-bottom:3px double #10b981;margin-bottom:30px;padding-bottom:15px;} h1{color:#10b981;margin:0;font-size:24pt;} .meta{display:flex;justify-content:space-between;margin-bottom:20px;font-size:10pt;font-weight:bold;color:#64748b;} table{width:100%;border-collapse:collapse;} th,td{border:1px solid #e2e8f0;padding:12px;text-align:left;font-size:10pt;} th{background:#f8fafc;color:#475569;text-transform:uppercase;font-size:9pt;letter-spacing:1px;}</style></head><body><div class="kop"><h1>SAPADESA</h1><p>ROWOSARI • LIMPUNG • BATANG</p></div><div class="meta"><span>LAPORAN HARIAN</span><span>TANGGAL: ${new Date(date).toLocaleDateString('id-ID', {dateStyle:'full'})}</span></div><table><thead><tr><th>Waktu</th><th>Nama Warga</th><th>Wilayah</th><th style="text-align:right">Nominal</th></tr></thead><tbody>${rows || '<tr><td colspan="4" style="text-align:center">Tidak ada transaksi</td></tr>'}</tbody></table></body></html>`);
        printWindow.document.close();
        printWindow.print();
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row gap-4 items-end bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                <div className="flex-1">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-2 block">Pilih Tanggal Laporan</label>
                    <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full p-4 bg-white border border-slate-200 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-primary/20" />
                </div>
                <button onClick={handlePrint} className="bg-slate-800 text-white px-8 py-4 rounded-2xl font-bold flex items-center justify-center gap-2 hover:bg-slate-900 transition-all shadow-lg shadow-slate-900/10"><DownloadIcon /> Cetak Semua</button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="p-6 rounded-3xl bg-emerald-50 border border-emerald-100"><p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Pemasukan</p><p className="text-2xl font-black text-emerald-700 mt-1">Rp{reports.reduce((s,i) => s+i.amount, 0).toLocaleString('id-ID')}</p></div>
                <div className="p-6 rounded-3xl bg-rose-50 border border-rose-100"><p className="text-[10px] font-black text-rose-600 uppercase tracking-widest">Pengeluaran</p><p className="text-2xl font-black text-rose-700 mt-1">Rp{expenses.reduce((s,i) => s+i.amount, 0).toLocaleString('id-ID')}</p></div>
                <div className="p-6 rounded-3xl bg-slate-50 border border-slate-100"><p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Jumlah Transaksi</p><p className="text-2xl font-black text-slate-700 mt-1">{reports.length}</p></div>
            </div>

            <div className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm">
                <table className="w-full text-sm text-left">
                    <thead><tr className="bg-slate-50/50 border-b border-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest"><th className="p-5">Waktu</th><th className="p-5">Warga</th><th className="p-5">Petugas</th><th className="p-5 text-right">Nominal</th></tr></thead>
                    <tbody className="divide-y divide-slate-100">
                        {loading ? <tr><td colSpan={4} className="p-10 text-center animate-pulse font-bold text-slate-300">Memproses Data...</td></tr> : 
                        reports.map(r => (
                            <tr key={r.id} className="hover:bg-slate-50/50 transition-colors">
                                <td className="p-5 font-bold text-slate-400">{new Date(r.timestamp).toLocaleTimeString('id-ID', {hour:'2-digit', minute:'2-digit'})}</td>
                                <td className="p-5">
                                    <p className="font-bold text-slate-700">{r.wargaName}</p>
                                    <p className="text-[10px] text-slate-400 uppercase tracking-tighter">RT {r.rtNumber}, {r.dukuhName}</p>
                                </td>
                                <td className="p-5 text-slate-500 font-medium">{r.petugasName}</td>
                                <td className="p-5 text-right font-bold text-emerald-600">Rp{r.amount.toLocaleString('id-ID')}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default DailyReport;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import type { Pengeluaran } from '@/types';
import { getAllPengeluaran, createPengeluaran, updatePengeluaran, deletePengeluaran, getAdminDashboardStats } from '@/services/api';
import Modal from '@/components/Modal';
import { TrashIcon, PencilIcon, BanknotesIcon, SearchIcon, ChevronDownIcon, DownloadIcon } from '@/components/icons';

const PengeluaranForm: React.FC<{
  pengeluaran?: Pengeluaran | null;
  onSave: (p: Omit<Pengeluaran, 'id'> | Pengeluaran) => void;
  onCancel: () => void;
}> = ({ pengeluaran, onSave, onCancel }) => {
  const [formData, setFormData] = useState({
    date: pengeluaran?.date ? new Date(pengeluaran.date).toISOString().split('T')[0] : new Date().toISOString().split('T')[0],
    description: pengeluaran?.description || '',
    amount: pengeluaran?.amount || 0,
  });

  return (
    <form onSubmit={(e) => { e.preventDefault(); onSave(pengeluaran ? { ...pengeluaran, ...formData, date: new Date(formData.date) } : { ...formData, date: new Date(formData.date) }); }} className="space-y-6">
      <div className="space-y-2">
        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Tanggal Transaksi</label>
        <input type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-primary outline-none font-semibold" required />
      </div>
      <div className="space-y-2">
        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Keterangan / Deskripsi</label>
        <input type="text" placeholder="Bensin, Gaji, Alat Kebersihan, dll" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-primary outline-none font-semibold" required />
      </div>
      <div className="space-y-2">
        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Jumlah Nominal</label>
        <div className="relative">
            <span className="absolute left-5 top-1/2 -translate-y-1/2 font-bold text-slate-400">Rp</span>
            <input type="number" value={formData.amount} onChange={e => setFormData({...formData, amount: Number(e.target.value)})} className="w-full pl-12 pr-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-primary outline-none font-bold" required />
        </div>
      </div>
      <div className="flex gap-3 pt-4">
        <button type="button" onClick={onCancel} className="flex-1 py-3.5 rounded-2xl font-bold text-slate-500 hover:bg-slate-100 transition-all">Batal</button>
        <button type="submit" className="flex-1 py-3.5 rounded-2xl font-bold bg-slate-800 text-white hover:bg-slate-900 shadow-lg shadow-slate-900/10 transition-all">Simpan Catatan</button>
      </div>
    </form>
  );
};

const AdminKeuanganPage: React.FC = () => {
    const [list, setList] = useState<Pengeluaran[]>([]);
    const [stats, setStats] = useState<any>(null);
    const [loading, setLoading] = useState(true);
    const [filters, setFilters] = useState({ search: '' });
    const [itemsPerPage, setItemsPerPage] = useState<number | 'all'>(10);
    const [currentPage, setCurrentPage] = useState(1);

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [selected, setSelected] = useState<Pengeluaran | null>(null);
    const [toDelete, setToDelete] = useState<Pengeluaran | null>(null);

    const fetchData = useCallback(async () => {
        setLoading(true);
        const [data, s] = await Promise.all([getAllPengeluaran(), getAdminDashboardStats()]);
        setList(data);
        setStats(s);
        setLoading(false);
    }, []);

    useEffect(() => { fetchData(); }, [fetchData]);

    const filtered = useMemo(() => {
        return list.filter(p => p.description.toLowerCase().includes(filters.search.toLowerCase()));
    }, [list, filters]);

    const paginated = useMemo(() => {
        if (itemsPerPage === 'all') return filtered;
        const start = (currentPage - 1) * itemsPerPage;
        return filtered.slice(start, start + itemsPerPage);
    }, [filtered, itemsPerPage, currentPage]);

    const totalPages = itemsPerPage === 'all' ? 1 : Math.ceil(filtered.length / itemsPerPage);

    return (
        <div className="space-y-6">
            <div className="bg-white p-6 rounded-3xl border border-slate-200/60 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
                <div>
                    <h1 className="text-2xl font-black text-slate-800 tracking-tight">Manajemen Keuangan</h1>
                    <p className="text-slate-500 text-sm font-medium">Monitoring arus kas dan operasional desa.</p>
                </div>
                <button onClick={() => { setSelected(null); setIsModalOpen(true); }} className="w-full md:w-auto bg-primary text-white px-6 py-3 rounded-2xl font-bold hover:bg-primary-focus shadow-lg shadow-primary/20 transition-all transform hover:-translate-y-0.5">+ Tambah Pengeluaran</button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <div className="bg-white p-6 rounded-3xl border border-slate-200/60 shadow-sm">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Saldo Saat Ini</p>
                    <p className="text-2xl font-black text-slate-800 mt-1 tracking-tight">Rp{stats?.balance.toLocaleString('id-ID')}</p>
                </div>
                <div className="bg-white p-6 rounded-3xl border border-slate-200/60 shadow-sm">
                    <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest">Total Pemasukan</p>
                    <p className="text-2xl font-black text-emerald-600 mt-1 tracking-tight">Rp{stats?.totalRevenue.toLocaleString('id-ID')}</p>
                </div>
                <div className="bg-white p-6 rounded-3xl border border-slate-200/60 shadow-sm">
                    <p className="text-[10px] font-black text-rose-500 uppercase tracking-widest">Total Pengeluaran</p>
                    <p className="text-2xl font-black text-rose-600 mt-1 tracking-tight">Rp{stats?.totalExpense.toLocaleString('id-ID')}</p>
                </div>
            </div>

            <div className="bg-white p-4 rounded-3xl border border-slate-200/60 shadow-sm space-y-4">
                <div className="flex flex-col md:flex-row gap-4 items-center">
                    <div className="relative flex-1 w-full">
                        <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                        <input type="text" placeholder="Cari keterangan pengeluaran..." className="w-full pl-11 pr-4 py-3 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-primary outline-none bg-slate-50 font-semibold" value={filters.search} onChange={e => setFilters({search: e.target.value})} />
                    </div>
                    <div className="flex items-center gap-3">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Baris</span>
                        <select value={itemsPerPage} onChange={e => { setItemsPerPage(e.target.value === 'all' ? 'all' : Number(e.target.value)); setCurrentPage(1); }} className="bg-white border border-slate-200 rounded-xl px-3 py-2 text-xs font-bold outline-none">
                            <option value={10}>10</option><option value={25}>25</option><option value="all">Semua</option>
                        </select>
                    </div>
                </div>
            </div>

            <div className="bg-white rounded-[2rem] border border-slate-200/60 shadow-sm overflow-hidden">
                <table className="w-full text-sm text-left">
                    <thead><tr className="bg-slate-50/50 border-b border-slate-100 text-[10px] font-black text-slate-400 uppercase tracking-widest"><th className="p-5">Tanggal</th><th className="p-5">Keterangan</th><th className="p-5 text-right">Nominal</th><th className="p-5 text-center">Aksi</th></tr></thead>
                    <tbody className="divide-y divide-slate-100">
                        {paginated.map(p => (
                            <tr key={p.id} className="hover:bg-slate-50/50 transition-colors">
                                <td className="p-5 font-bold text-slate-400">{new Date(p.date).toLocaleDateString('id-ID', {day:'2-digit', month:'short', year:'numeric'})}</td>
                                <td className="p-5 font-bold text-slate-700">{p.description}</td>
                                <td className="p-5 text-right font-black text-rose-600">Rp{p.amount.toLocaleString('id-ID')}</td>
                                <td className="p-5 text-center">
                                    <div className="flex justify-center gap-2">
                                        <button onClick={() => { setSelected(p); setIsModalOpen(true); }} className="p-2 text-slate-400 hover:text-indigo-600 rounded-xl hover:bg-indigo-50 transition-all"><PencilIcon className="text-xl" /></button>
                                        <button onClick={() => setToDelete(p)} className="p-2 text-slate-400 hover:text-rose-600 rounded-xl hover:bg-rose-50 transition-all"><TrashIcon className="text-xl" /></button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                {itemsPerPage !== 'all' && totalPages > 1 && (
                    <div className="p-5 bg-slate-50/30 border-t border-slate-100 flex justify-center gap-2">
                        <button onClick={() => setCurrentPage(p => Math.max(1, p - 1))} disabled={currentPage === 1} className="p-2 text-slate-400 disabled:opacity-30"><i className="fa-solid fa-chevron-left"></i></button>
                        <span className="bg-primary text-white px-3 py-1 rounded-xl text-xs font-bold">{currentPage} / {totalPages}</span>
                        <button onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))} disabled={currentPage === totalPages} className="p-2 text-slate-400 disabled:opacity-30"><i className="fa-solid fa-chevron-right"></i></button>
                    </div>
                )}
            </div>

            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={selected ? 'Edit Catatan' : 'Tambah Pengeluaran'}>
                <PengeluaranForm pengeluaran={selected} onSave={async (d) => { if ('id' in d) await updatePengeluaran(d.id, d as Pengeluaran); else await createPengeluaran(d as any); fetchData(); setIsModalOpen(false); }} onCancel={() => setIsModalOpen(false)} />
            </Modal>

            <Modal isOpen={!!toDelete} onClose={() => setToDelete(null)} title="Hapus Catatan">
                {toDelete && (
                    <div className="text-center py-4">
                        <p className="font-bold text-slate-700">Hapus catatan <span className="text-rose-600">"{toDelete.description}"</span>?</p>
                        <div className="mt-8 flex gap-3">
                            <button onClick={() => setToDelete(null)} className="flex-1 py-3.5 rounded-2xl font-bold text-slate-500 hover:bg-slate-100 transition-all">Batal</button>
                            <button onClick={async () => { await deletePengeluaran(toDelete.id); fetchData(); setToDelete(null); }} className="flex-1 py-3.5 rounded-2xl font-bold bg-rose-500 text-white shadow-lg shadow-rose-500/20">Hapus</button>
                        </div>
                    </div>
                )}
            </Modal>
        </div>
    );
};

