                    </div>
                </div>
                <table>
                    <thead><tr><th>Tanggal</th><th style="text-align:right">Total Pemasukan</th><th style="text-align:right">Total Pengeluaran</th><th style="text-align:right">Netto Harian</th></tr></thead>
