export const getTransactionsByWargaId = async (wargaId: string, days: number): Promise<Transaksi[]> => {
    const limitDate = new Date();
    limitDate.setDate(limitDate.getDate() - days);
    return transactions.filter(tx => tx.wargaId === wargaId && tx.timestamp >= limitDate).sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime());
};

export const createTransaksi = async (txData: {wargaId: string, petugasId: string, amount: number, status?: TransactionStatus}): Promise<Transaksi> => {
    await delay(300);
    const status = txData.status || 'LUNAS';
    const newTx: Transaksi = {
        ...txData,
        status,
        category: 'IURAN', // Transaksi harian masuk kategori IURAN
        id: `tx${Date.now()}`,
        timestamp: new Date(),
    };

    const warga = wargas.find(w => w.id === txData.wargaId);
    if (warga) {
        if (status === 'HUTANG') {
            warga.totalDebt += txData.amount;
        }
    }

    transactions.unshift(newTx);
    return newTx;
};

export const payDebt = async (wargaId: string, petugasId: string, amountToPay: number): Promise<Transaksi> => {
    await delay(300);
    const warga = wargas.find(w => w.id === wargaId);
    if (!warga) throw new Error('Warga tidak ditemukan');

    if (amountToPay > warga.totalDebt) {
        throw new Error('Jumlah pembayaran melebihi total tunggakan');
    }

    const newTx: Transaksi = {
        id: `tx-pay-${Date.now()}`,
        timestamp: new Date(),
        wargaId,
        petugasId,
        amount: amountToPay,
        status: 'LUNAS',
        category: 'TUNGGAKAN' // Penanda bahwa ini adalah cicilan hutang, bukan iuran hari ini
    };

    warga.totalDebt -= amountToPay;
    transactions.unshift(newTx);
    return newTx;
};

export const deleteTransaksi = async (id: string) => { transactions = transactions.filter(t => t.id !== id); };

// --- Reports API ---

export const getReports = async (f: { startDate: Date, endDate: Date, dukuhId?: number, rtId?: number }): Promise<any[]> => {
    const start = new Date(f.startDate);
    start.setHours(0,0,0,0);
    const end = new Date(f.endDate);
    end.setHours(23,59,59,999);

    let filtered = transactions.filter(tx => tx.timestamp >= start && tx.timestamp <= end);

    return filtered.map(tx => {
        const w = wargas.find(w => w.id === tx.wargaId);
        const p = petugases.find(p => p.id === tx.petugasId);
        return {
            ...tx,
            wargaName: w?.name || 'N/A',
            petugasName: p?.name || 'N/A',
            dukuhName: dukuhs.find(d => d.id === w?.dukuhId)?.name || 'N/A',
            rtNumber: rts.find(r => r.id === w?.rtId)?.number || 'N/A'
        };
    }).filter(row => {
        if (f.dukuhId && row.dukuhName !== dukuhs.find(d => d.id === f.dukuhId)?.name) return false;
        if (f.rtId && row.rtNumber !== rts.find(r => r.id === f.rtId)?.number) return false;
        return true;
    });
};

export const getAdminDashboardStats = async () => {
    const totalRevenue = transactions.filter(tx => tx.status === 'LUNAS').reduce((sum, tx) => sum + tx.amount, 0);
    const totalDebt = wargas.reduce((sum, w) => sum + (w.totalDebt || 0), 0);
    const totalExpense = pengeluarans.reduce((sum, p) => sum + p.amount, 0);
    return {
        totalRevenue,
        totalExpense,
        balance: totalRevenue - totalExpense,
        totalWarga: wargas.length,
        totalPetugas: petugases.length,
        totalDebt,
        monthlyRevenue: [] 
    };
};

export const getPublicDashboardStats = async (): Promise<PublicStats> => {
    const today = new Date();
    const transactionsThisMonth = transactions.filter(tx => tx.status === 'LUNAS' && tx.timestamp.getMonth() === today.getMonth() && tx.timestamp.getFullYear() === today.getFullYear());
    return {
        totalWarga: wargas.length,
        totalTransaksiBulanIni: transactionsThisMonth.length,
        totalDanaTerkumpulBulanIni: transactionsThisMonth.reduce((sum, tx) => sum + tx.amount, 0)
    };
};

export const getParticipationReport = async (m: number, y: number): Promise<ParticipationStats[]> => {
    const report: ParticipationStats[] = rts.map(rt => {
        const wargaInRT = wargas.filter(w => w.rtId === rt.id);
        const activeInRT = wargaInRT.filter(w => transactions.some(tx => tx.wargaId === w.id && tx.timestamp.getMonth() === m - 1 && tx.timestamp.getFullYear() === y));

        return {
            rtId: rt.id,
            rtNumber: rt.number,
            totalWarga: wargaInRT.length,
            activeWarga: activeInRT.length,
            participationRate: wargaInRT.length > 0 ? (activeInRT.length / wargaInRT.length) * 100 : 0,
            unpaidWargaList: wargaInRT.filter(w => !activeInRT.includes(w))
        };
    });
    return report;
};

// --- Pengeluaran API ---

export const getAllPengeluaran = async (): Promise<Pengeluaran[]> => [...pengeluarans].sort((a,b) => b.date.getTime() - a.date.getTime());

export const getPengeluaran = async (f: { startDate: Date, endDate: Date }) => {
    const start = new Date(f.startDate);
    start.setHours(0,0,0,0);
    const end = new Date(f.endDate);
    end.setHours(23,59,59,999);
    return pengeluarans.filter(p => p.date >= start && p.date <= end);
};

export const createPengeluaran = async (data: Omit<Pengeluaran, 'id'>): Promise<Pengeluaran> => {
    const newP = { ...data, id: `exp${Date.now()}` };
    pengeluarans.push(newP);
    return newP;
};

export const updatePengeluaran = async (id: string, data: Partial<Pengeluaran>): Promise<Pengeluaran> => {
    const idx = pengeluarans.findIndex(p => p.id === id);
    if (idx > -1) {
        pengeluarans[idx] = { ...pengeluarans[idx], ...data };
        return pengeluarans[idx];
    }
    throw new Error('Pengeluaran not found');
};

export const deletePengeluaran = async (id: string) => {
    pengeluarans = pengeluarans.filter(p => p.id !== id);
};

// --- Schedule API ---

export const getSchedule = async () => schedule;
export const updateSchedule = async (d: string, s: any) => { schedule[d] = s; return schedule; };

export const getScheduleForToday = async () => {
    const day = ['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'][new Date().getDay()];
    const s = schedule[day];
    return { 
        isHoliday: s === 'libur', 
        dukuhIds: s === 'libur' ? [] : s, 
        dukuhNames: s === 'libur' ? [] : (s as number[]).map(id => dukuhs.find(d => d.id === id)?.name || '')
    };
};

export const getScheduleForDate = async (d: Date) => {
    const day = ['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'][d.getDay()];
    const s = schedule[day];
    return { 
        isHoliday: s === 'libur', 
        dukuhNames: s === 'libur' ? [] : (s as number[]).map(id => dukuhs.find(d => d.id === id)?.name || '')
    };
};

// --- Other API ---

export const checkIfWargaPaidToday = async (id: string) => {
    const today = new Date().toDateString();
    // Penting: Hanya mengecek transaksi kategori IURAN. Cicilan tunggakan diabaikan.
    return transactions.some(tx => tx.wargaId === id && tx.timestamp.toDateString() === today && tx.category === 'IURAN');
};

export const getUnpaidWargaForToday = async () => {
    const sched = await getScheduleForToday();
    if (sched.isHoliday) return [];
    return wargas.filter(w => sched.dukuhIds.includes(w.dukuhId) && !transactions.some(tx => tx.wargaId === w.id && tx.timestamp.toDateString() === new Date().toDateString() && tx.category === 'IURAN'));
};

export const getUnpaidWargaForDate = async (d: Date) => {
    const sched = await getScheduleForDate(d);
    if (sched.isHoliday) return [];
    return wargas.filter(w => !transactions.some(tx => tx.wargaId === w.id && tx.timestamp.toDateString() === d.toDateString() && tx.category === 'IURAN'));
};

export const getPetugasDailySummary = async (id: string) => {
    const today = new Date().toDateString();
    const todayTx = transactions.filter(tx => tx.petugasId === id && tx.timestamp.toDateString() === today && tx.status === 'LUNAS');
    return { total: todayTx.reduce((s, tx) => s + tx.amount, 0), count: todayTx.length };
};

// --- Messaging API ---

export const getMessages = async () => [...messages].sort((a,b) => b.timestamp.getTime() - a.timestamp.getTime());

export const sendMessage = async (data: { name: string, contact: string, message: string }) => {
    const newMsg: ContactMessage = {
        ...data,
        id: `msg${Date.now()}`,
        timestamp: new Date(),
        isRead: false
    };
    messages.push(newMsg);
    return newMsg;
};

export const markMessageAsRead = async (id: string) => {
    const msg = messages.find(m => m.id === id);
    if (msg) msg.isRead = true;
};

export const deleteMessage = async (id: string) => {
    messages = messages.filter(m => m.id !== id);
};

// --- Announcements API ---

export const getAnnouncements = async () => [...announcements].sort((a,b) => b.date.getTime() - a.date.getTime());

export const getActiveAnnouncements = async (): Promise<Announcement[]> => announcements.filter(a => a.isActive);

export const createAnnouncement = async (data: Omit<Announcement, 'id' | 'date'>) => {
    const newAnn: Announcement = {
        ...data,
        id: `ann${Date.now()}`,
        date: new Date()
    };
    announcements.push(newAnn);
    return newAnn;
};

export const updateAnnouncement = async (id: string, data: Partial<Announcement>) => {
    const idx = announcements.findIndex(a => a.id === id);
    if (idx > -1) {
        announcements[idx] = { ...announcements[idx], ...data };
        return announcements[idx];
    }
    throw new Error('Announcement not found');
};

export const deleteAnnouncement = async (id: string) => {
    announcements = announcements.filter(a => a.id !== id);
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { FC } from 'react';
import type { Warga, TransactionStatus } from '@/types';
import { getWargaById, createTransaksi, payDebt, getDukuhById, getRTById, checkIfWargaPaidToday } from '@/services/api';
import { useAuth } from '@/context/AuthContext';
import { CheckCircleIcon, QrCodeIcon, SearchIcon, XIcon, BanknotesIcon } from '@/components/icons';
import Modal from '@/components/Modal';
import jsQR from 'jsqr';

const PetugasScanPage: FC = () => {
    const [mode, setMode] = useState<'scan' | 'manual'>('scan');
    const [wargaId, setWargaId] = useState('');
    const [warga, setWarga] = useState<Warga | null>(null);
    const [hasPaidToday, setHasPaidToday] = useState(false);
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [success, setSuccess] = useState(false);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [modalTitle, setModalTitle] = useState('Berhasil');

    const [isPayingDebt, setIsPayingDebt] = useState(false);
    const [debtInput, setDebtInput] = useState<number>(0);

    const videoRef = useRef<HTMLVideoElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [isScanning, setIsScanning] = useState(false);
    const isScanningRef = useRef(false); 

    const { petugas } = useAuth();

    const resetState = useCallback(() => {
        setWarga(null);
        setWargaId('');
        setError('');
        setSuccess(false);
        setLoading(false);
        setHasPaidToday(false);
        setIsPayingDebt(false);
        setDebtInput(0);
        if (mode === 'scan') {
            setIsScanning(true);
            isScanningRef.current = true;
        }
    }, [mode]);

    const fetchWarga = useCallback(async (id: string) => {
        setIsScanning(false);
        isScanningRef.current = false;
        setLoading(true);
        setError('');

        try {
            const data = await getWargaById(id);
            if (data) {
                setWarga(data);
                setDebtInput(data.totalDebt); 
                const paidToday = await checkIfWargaPaidToday(id);
                setHasPaidToday(paidToday);
            } else {
                setError(`ID Warga "${id}" tidak ditemukan.`);
                if (mode === 'scan') {
                    setTimeout(() => {
                        setIsScanning(true);
                        isScanningRef.current = true;
                    }, 3000);
                }
            }
        } catch (err) {
            setError('Gagal memuat data warga.');
            if (mode === 'scan') {
                setTimeout(() => {
                    setIsScanning(true);
                    isScanningRef.current = true;
                }, 3000);
            }
        } finally {
            setLoading(false);
        }
    }, [mode]);

    useEffect(() => {
        let stream: MediaStream | null = null;
        let animationFrameId: number;

        const tick = () => {
            if (!isScanningRef.current) {
                animationFrameId = requestAnimationFrame(tick);
                return;
            }

            if (videoRef.current && videoRef.current.readyState === videoRef.current.HAVE_ENOUGH_DATA && canvasRef.current) {
                const canvas = canvasRef.current;
                const video = videoRef.current;
                canvas.height = video.videoHeight;
                canvas.width = video.videoWidth;
                const ctx = canvas.getContext('2d', { willReadFrequently: true });
                if (ctx) {
                    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
                    try {
                        const code = jsQR(imageData.data, imageData.width, imageData.height, { inversionAttempts: "dontInvert" });
                        if (code && code.data) {
                            isScanningRef.current = false;
                            setIsScanning(false);
                            fetchWarga(code.data);
                            return; 
                        }
                    } catch (err) { console.error("jsQR error:", err); }
                }
            }
            animationFrameId = requestAnimationFrame(tick);
        };

        const startCamera = async () => {
            if (mode !== 'scan' || warga || success) return;
            try {
                stream = await navigator.mediaDevices.getUserMedia({ 
                    video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } 
                });
                if (videoRef.current) {
                    videoRef.current.srcObject = stream;
                    videoRef.current.onloadedmetadata = () => {
                        videoRef.current?.play().catch(e => console.error("Play error:", e));
                        setIsScanning(true);
                        isScanningRef.current = true;
                        tick();
                    };
                }
            } catch (err) {
                console.error("Camera error:", err);
                setError('Akses kamera ditolak.');
                setMode('manual');
            }
        };

        if (mode === 'scan' && !warga && !success) startCamera();
        return () => {
            if (stream) stream.getTracks().forEach(track => track.stop());
            cancelAnimationFrame(animationFrameId);
            isScanningRef.current = false;
        };
    }, [mode, warga, success, fetchWarga]);

    const handleManualSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (wargaId.length === 6) fetchWarga(wargaId);
        else setError('ID Warga harus 6 digit.');
    };

    const handleSavePayment = async (status: TransactionStatus) => {
        if (!warga || !petugas) return;
        setLoading(true);
        try {
            await createTransaksi({
                wargaId: warga.id,
                petugasId: petugas.id,
                amount: warga.dailyFee,
                status: status
            });
            setModalTitle(status === 'LUNAS' ? 'Pembayaran Berhasil' : 'Tunggakan Dicatat');
            setSuccess(true);
            setIsModalOpen(true);
            setTimeout(() => { setIsModalOpen(false); resetState(); }, 2000);
        } catch (err: any) { setError(err.message || 'Gagal menyimpan.'); }
        finally { setLoading(false); }
    };

    const handlePayDebt = async () => {
        if (!warga || !petugas || debtInput <= 0) return;
        if (debtInput > warga.totalDebt) {
            setError('Nominal melebihi total tunggakan!');
            return;
        }

        setLoading(true);
        try {
            await payDebt(warga.id, petugas.id, debtInput);
            setModalTitle('Pembayaran Tunggakan Berhasil');
            setSuccess(true);
            setIsModalOpen(true);
            setTimeout(() => { setIsModalOpen(false); resetState(); }, 2000);
        } catch (err: any) { setError(err.message || 'Gagal menyimpan.'); }
        finally { setLoading(false); }
    };

    const getDukuhName = (id: number) => getDukuhById(id)?.name || 'N/A';
    const getRTNumber = (id: number) => getRTById(id)?.number || 'N/A';

    return (
        <div className="flex-grow p-4 max-w-md mx-auto w-full">
            {!warga && (
                <div className="flex bg-white p-1.5 rounded-2xl shadow-sm border border-slate-200 mb-6">
                    <button onClick={() => setMode('scan')} className={`flex-1 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-2 ${mode === 'scan' ? 'bg-slate-800 text-white shadow-md' : 'text-slate-400'}`}>
                        <QrCodeIcon className="text-lg" /> Scan QR
                    </button>
                    <button onClick={() => setMode('manual')} className={`flex-1 py-2.5 rounded-xl font-bold text-sm transition-all flex items-center justify-center gap-2 ${mode === 'manual' ? 'bg-slate-800 text-white shadow-md' : 'text-slate-400'}`}>
                        <SearchIcon className="text-lg" /> Manual
                    </button>
                </div>
            )}

            {!warga && mode === 'scan' && (
                <div className="relative aspect-square w-full bg-slate-900 rounded-[2.5rem] overflow-hidden shadow-2xl border-4 border-white animate-fade-in">
                    <video ref={videoRef} className="w-full h-full object-cover" playsInline autoPlay muted />
                    <canvas ref={canvasRef} className="hidden" />
                    <div className="absolute inset-0 border-[45px] border-slate-900/40 pointer-events-none">
                        <div className="w-full h-full border-2 border-primary/50 rounded-2xl relative">
                            <div className="absolute top-0 left-0 w-10 h-10 border-t-4 border-l-4 border-primary rounded-tl-lg"></div>
                            <div className="absolute top-0 right-0 w-10 h-10 border-t-4 border-r-4 border-primary rounded-tr-lg"></div>
                            <div className="absolute bottom-0 left-0 w-10 h-10 border-b-4 border-l-4 border-primary rounded-bl-lg"></div>
                            <div className="absolute bottom-0 right-0 w-10 h-10 border-b-4 border-r-4 border-primary rounded-br-lg"></div>
                            <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-transparent via-primary to-transparent animate-[scan_2.5s_linear_infinite]"></div>
                        </div>
                    </div>
                </div>
            )}

            {!warga && mode === 'manual' && (
                <div className="animate-fade-in space-y-4">
                    <form onSubmit={handleManualSubmit} className="bg-white p-8 rounded-[2rem] shadow-sm border border-slate-200">
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-1">ID Warga (6 Digit)</label>
                        <input type="tel" value={wargaId} onChange={(e) => setWargaId(e.target.value.replace(/\D/g, ''))} maxLength={6} placeholder="100001" className="w-full text-2xl font-bold px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-primary/10 focus:border-primary outline-none transition-all" autoFocus />
                        <button type="submit" disabled={loading} className="w-full mt-6 bg-slate-800 text-white font-bold py-4 rounded-2xl hover:bg-slate-900 shadow-xl shadow-slate-900/10 transition-all">Cari Warga</button>
                    </form>
                </div>
            )}

            {error && !warga && (
                <div className="mt-4 p-4 bg-rose-50 border border-rose-100 text-rose-600 rounded-2xl text-xs font-bold flex items-center gap-3 animate-shake uppercase tracking-tight">
                    <XIcon /> <p>{error}</p>
                </div>
            )}

            {warga && !success && (
                <div className="bg-white p-6 rounded-[2.5rem] shadow-xl border border-slate-200 animate-slide-in-up">
                    <div className="text-center mb-6">
                        <div className="w-16 h-16 bg-emerald-50 rounded-2xl flex items-center justify-center mx-auto mb-4 border border-emerald-100">
                            <QrCodeIcon className="text-3xl text-emerald-500" />
                        </div>
                        <h2 className="text-2xl font-black text-slate-800 tracking-tight">{warga.name}</h2>
                        <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">ID: {warga.id} • RT {getRTNumber(warga.rtId)}, {getDukuhName(warga.dukuhId)}</p>
                    </div>

                    <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 mb-6 text-center">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Tarif Iuran Hari Ini</p>
                        <p className="text-4xl font-black text-slate-800">Rp{warga.dailyFee.toLocaleString('id-ID')}</p>

                        {warga.totalDebt > 0 && (
                            <div className="mt-5 pt-5 border-t border-slate-200/60">
                                <p className="text-[10px] font-black text-rose-400 uppercase tracking-widest mb-1">Total Tunggakan</p>
                                <p className="text-2xl font-black text-rose-600">Rp{warga.totalDebt.toLocaleString('id-ID')}</p>
                            </div>
                        )}
                    </div>

                    {isPayingDebt ? (
                        <div className="space-y-4 animate-fade-in">
                            <div className="bg-slate-900 p-6 rounded-3xl border border-slate-800 shadow-2xl">
                                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 text-center text-white">Input Nominal Bayar Tunggakan</label>
                                <div className="relative">
                                    <span className="absolute left-4 top-1/2 -translate-y-1/2 font-black text-slate-500">Rp</span>
                                    <input 
                                        type="number" 
                                        value={debtInput} 
                                        onChange={(e) => {
                                            const val = Number(e.target.value);
                                            setDebtInput(val > warga.totalDebt ? warga.totalDebt : val);
                                        }}
                                        max={warga.totalDebt}
                                        className="w-full pl-11 pr-4 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white font-black text-xl outline-none focus:ring-2 focus:ring-primary"
                                    />
                                </div>
                                <div className="grid grid-cols-2 gap-3 mt-4">
                                    <button onClick={() => setIsPayingDebt(false)} className="py-3 px-4 rounded-xl font-bold text-slate-400 bg-slate-800 border border-slate-700 hover:text-white transition-all">Batal</button>
                                    <button onClick={handlePayDebt} disabled={loading || debtInput <= 0} className="py-3 px-4 rounded-xl font-bold bg-primary text-white shadow-lg shadow-primary/20 transition-all disabled:opacity-50">Bayar Sekarang</button>
                                </div>
                            </div>
                        </div>
                    ) : (
                        <div className="space-y-3">
                            <button onClick={() => handleSavePayment('LUNAS')} disabled={loading || hasPaidToday} className={`w-full font-bold py-4 rounded-2xl shadow-lg transition-all flex items-center justify-center gap-2 ${hasPaidToday ? 'bg-emerald-100 text-emerald-500 cursor-not-allowed' : 'bg-emerald-500 text-white shadow-emerald-500/20 hover:bg-emerald-600'}`}>
                                <CheckCircleIcon /> {hasPaidToday ? 'Iuran Sudah Tercatat Hari Ini' : 'Bayar Tunai (Iuran Hari Ini)'}
                            </button>

                            {!hasPaidToday && (
                                <button onClick={() => handleSavePayment('HUTANG')} disabled={loading} className="w-full bg-amber-500 text-white font-bold py-4 rounded-2xl shadow-lg shadow-amber-500/20 hover:bg-amber-600 transition-all disabled:opacity-50">
                                    Catat Tunggakan (Iuran Hari Ini)
                                </button>
                            )}

                            {warga.totalDebt > 0 && (
