            setLoading(true);
            const [all, d, r] = await Promise.all([getAllWarga(), getAllDukuh(), getAllRT()]);
            // Filter hanya yang memiliki tunggakan
            const withDebt = all.filter(w => (w.totalDebt || 0) > 0).sort((a,b) => (b.totalDebt || 0) - (a.totalDebt || 0));
            setList(withDebt);
            setDukuhList(d);
            setRtList(r);
