                const total = reports
                    .filter(r => new Date(r.timestamp).toDateString() === d.toDateString())
                    .reduce((sum, r) => sum + r.amount, 0);

                days.push({ name: dateStr, total });
            }
            setChartData(days);
        };
        loadDashboardData();
    }, []);

