            </div>

            <div className="bg-white p-6 md:p-8 rounded-[2.5rem] border border-slate-200/60 shadow-sm overflow-hidden">
                <div className="mb-8">
                    <h3 className="text-xl font-extrabold text-slate-800 tracking-tight">Grafik Pemasukan</h3>
