const PublicHomePage: React.FC = () => {
  const [wargaId, setWargaId] = useState('');
  const [warga, setWarga] = useState<Warga | null>(null);
  const [transactions, setTransactions] = useState<Transaksi[]>([]);
  const [hasPaidToday, setHasPaidToday] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [stats, setStats] = useState<PublicStats | null>(null);

  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [credential, setCredential] = useState('');
  const [isPasswordVisible, setIsPasswordVisible] = useState(false);
  const [loginError, setLoginError] = useState('');
  const [loginLoading, setLoginLoading] = useState(false);

  const resultRef = useRef<HTMLDivElement>(null);
  const navigate = useNavigate();
  const { loginAdmin: authLoginAdmin, loginPetugas: authLoginPetugas } = useAuth();

  useEffect(() => {
      const fetchPublicData = async () => {
          try {
              const [announcementData, statsData] = await Promise.all([getActiveAnnouncements(), getPublicDashboardStats()]);
              setAnnouncements(announcementData);
              setStats(statsData);
          } catch (e) {
              console.error("Error loading public data", e);
          }
      };
      fetchPublicData();
  }, []);

  const handleSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (wargaId.length !== 6) {
      setError('ID Warga harus 6 digit.');
      setWarga(null);
      return;
    }
    setLoading(true);
    setError(null);
    try {
      const wargaData = await getWargaById(wargaId);
      if (wargaData) {
        setWarga(wargaData);
        const [transactionData, paidToday] = await Promise.all([
            getTransactionsByWargaId(wargaId, 10),
            checkIfWargaPaidToday(wargaId)
        ]);
        setTransactions(transactionData);
        setHasPaidToday(paidToday);

        // Auto-scroll ke hasil setelah loading selesai
        setTimeout(() => {
            resultRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }, 100);
      } else {
        setError('ID Warga tidak ditemukan. Pastikan nomor ID benar.');
        setWarga(null);
      }
    } catch (err) {
      setError('Terjadi kesalahan saat mencari data.');
    } finally {
      setLoading(false);
    }
  };

  const handleLoginSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!credential) {
        setLoginError('PIN atau Password tidak boleh kosong.');
        return;
    }
    setLoginLoading(true);
    setLoginError('');

    try {
        const petugas = await loginPetugas(credential);
        if (petugas) {
            authLoginPetugas(petugas);
            navigate('/petugas/dashboard');
            return;
        }

        const admin = await loginAdmin('admin', credential);
        if (admin) {
            authLoginAdmin(admin);
            navigate('/admin/dashboard');
            return;
        }

        setLoginError('PIN atau Password salah.');
        setCredential('');

    } catch (err) {
        setLoginError('Terjadi kesalahan. Silakan coba lagi.');
        setCredential('');
    } finally {
        setLoginLoading(false);
    }
  };

  const openLoginModal = () => {
      setIsLoginModalOpen(true);
      setLoginError('');
      setCredential('');
  };

  const togglePasswordVisibility = () => setIsPasswordVisible(!isPasswordVisible);

  const getDukuhName = (id: number) => getDukuhById(id)?.name || 'N/A';
  const getRTNumber = (id: number) => getRTById(id)?.number || 'N/A';

  return (
    <>
      <div className="min-h-screen bg-white text-slate-800 flex flex-col">
        <div className="absolute top-0 left-0 w-full h-4 bg-teal-400"></div>
        <header className="container mx-auto px-4 sm:px-6 lg:px-8 py-5">
            <div className="flex justify-between items-center">
                <Link to="/" className="flex items-center">
                    <div className="bg-slate-800 text-white font-bold text-lg px-4 py-2 rounded-md shadow-sm -skew-x-12">
                        SapaDesa
                    </div>
                </Link>
                <nav className="hidden md:flex items-center space-x-8">
                    <Link to="/" className="text-primary font-semibold transition-colors">Home</Link>
                    <Link to="/tips" className="text-slate-600 hover:text-primary transition-colors font-medium">Tips Sampah</Link>
                    <Link to="/contact" className="text-slate-600 hover:text-primary transition-colors font-medium">Kontak</Link>
                </nav>
                <div className="flex items-center gap-4">
                     <button 
                      onClick={openLoginModal}
                      className="bg-slate-100 text-slate-700 text-sm font-semibold px-4 py-2 rounded-lg hover:bg-slate-200 transition-colors shadow-sm border border-slate-200"
                    >
                      Login Petugas/Admin
                    </button>
                    <button onClick={() => setIsMobileMenuOpen(true)} className="md:hidden p-2 text-slate-600 hover:text-primary" aria-label="Open menu">
                        <MenuIcon className="text-2xl" />
                    </button>
                </div>
            </div>
        </header>

        {isMobileMenuOpen && (
            <div className="fixed inset-0 bg-white z-50 flex flex-col animate-fade-in md:hidden">
                <div className="flex justify-between items-center p-4 border-b">
                    <div className="bg-slate-800 text-white font-bold text-lg px-4 py-2 rounded-md shadow-sm -skew-x-12">
                        SapaDesa
                    </div>
                    <button onClick={() => setIsMobileMenuOpen(false)} className="p-2 text-slate-600" aria-label="Close menu">
                        <XIcon className="text-2xl" />
                    </button>
                </div>
                <nav className="flex flex-col items-center justify-center flex-grow space-y-8">
                    <Link to="/" onClick={() => setIsMobileMenuOpen(false)} className="text-2xl font-semibold text-primary hover:text-primary">Home</Link>
                    <Link to="/tips" onClick={() => setIsMobileMenuOpen(false)} className="text-2xl font-semibold text-slate-700 hover:text-primary">Tips Sampah</Link>
                    <Link to="/contact" onClick={() => setIsMobileMenuOpen(false)} className="text-2xl font-semibold text-slate-700 hover:text-primary">Kontak</Link>
                </nav>
            </div>
        )}

        <main className="flex-grow">
            <section id="cek-status-form" className="container mx-auto px-4 sm:px-6 lg:px-8 py-10 md:py-16">
                <div className="grid lg:grid-cols-2 gap-12 items-center">
                    <div className="animate-fade-in">
                        <p className="font-semibold text-teal-500 text-lg uppercase tracking-widest">#SapaDesa_Rowosari</p>
                        <h1 className="font-display text-4xl md:text-5xl lg:text-6xl font-black text-slate-800 mt-2 leading-tight">
                            Pantau Retribusi <span className="text-primary underline decoration-teal-100 decoration-8 underline-offset-8">Sampah</span> Anda
                        </h1>
                        <p className="mt-6 text-slate-600 max-w-lg text-lg font-medium leading-relaxed">
                            Pastikan iuran kebersihan rumah Anda tercatat dengan benar. Masukkan 6 digit ID Warga Anda di bawah ini.
                        </p>

                        <form onSubmit={handleSearch} className="mt-10">
                          <div className="flex flex-col sm:flex-row rounded-3xl overflow-hidden shadow-2xl shadow-primary/10 border-2 border-slate-100 bg-white p-2">
