                              type="text"
                              value={wargaId}
                              onChange={(e) => setWargaId(e.target.value.replace(/\D/g, ''))}
                              placeholder="Masukkan 6 Digit ID Warga"
                              maxLength={6}
                              className="flex-grow px-6 py-4 bg-transparent focus:outline-none font-bold text-xl placeholder:text-slate-300 placeholder:font-medium"
                            />
                            <button
                              type="submit"
                              disabled={loading}
                              className="bg-emerald-500 text-white font-black py-4 px-10 rounded-2xl hover:bg-emerald-600 transition-all duration-300 disabled:bg-slate-400 flex items-center justify-center gap-3 shadow-lg shadow-emerald-500/30"
                            >
                              {loading ? (
                                  <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                              ) : <SearchIcon className="text-xl"/>}
                              {loading ? 'Mencari...' : 'LIHAT STATUS'}
                            </button>
