                amount: warga.dailyFee,
                status: 'LUNAS',
                category: 'IURAN'
            });
        });
        if (date.getDay() === 1) {
            pengeluarans.push({
                id: `exp-dummy-${i}`,
                date: new Date(date),
                description: i % 2 === 0 ? 'Bensin Motor Tossa' : 'Servis Rutin Kendaraan',
                amount: i % 2 === 0 ? 45000 : 150000
            });
        }
    }
};

