  useEffect(() => {
      const fetchPublicData = async () => {
          try {
              const [announcementData, statsData, tData] = await Promise.all([
                  getActiveAnnouncements(), 
                  getPublicDashboardStats(),
                  getPublicTransparencyData()
              ]);
              setAnnouncements(announcementData);
              setStats(statsData);
              setTransparencyData(tData);
          } catch (e) {
              console.error("Error loading public data", e);
          }
      };
      fetchPublicData();
