                                </button>
                            )}

                            {/* Tombol Lunas Harian */}
                            {todayTx?.status === 'LUNAS' ? (
                                <div className="w-full bg-emerald-100 text-emerald-600 font-bold py-4 rounded-2xl flex items-center justify-center gap-2 text-sm uppercase tracking-widest border border-emerald-200">
